INSERT INTO public.legal_sources(source_id,title,authority,source_url,official_host,official_role,scope_levels,notes) VALUES('mx_dof','Diario Oficial de la Federación','Diario Oficial de la Federación','https://dof.gob.mx/index.php','dof.gob.mx','official_publication',ARRAY['federal','treaties']::text[],'Índice leído. El archivo histórico, sus ediciones y los documentos vinculados aún no están inventariados ni incorporados.') ON CONFLICT(source_id) DO UPDATE SET title=excluded.title,authority=excluded.authority,source_url=excluded.source_url,official_host=excluded.official_host,official_role=excluded.official_role,scope_levels=excluded.scope_levels,notes=excluded.notes;
INSERT INTO public.legal_sources(source_id,title,authority,source_url,official_host,official_role,scope_levels,notes) VALUES('mx_diputados','Biblioteca de Leyes de la Cámara de Diputados','Cámara de Diputados del H. Congreso de la Unión','https://www.diputados.gob.mx/LeyesBiblio/index.htm','www.diputados.gob.mx','official_compilation',ARRAY['federal']::text[],'Índice con timeout. Se localizaron documentos oficiales; no se certifica actualidad ni cobertura íntegra del catálogo.') ON CONFLICT(source_id) DO UPDATE SET title=excluded.title,authority=excluded.authority,source_url=excluded.source_url,official_host=excluded.official_host,official_role=excluded.official_role,scope_levels=excluded.scope_levels,notes=excluded.notes;
INSERT INTO public.legal_sources(source_id,title,authority,source_url,official_host,official_role,scope_levels,notes) VALUES('mx_ojn','Orden Jurídico Nacional','Secretaría de Gobernación / Unidad General de Asuntos Jurídicos','https://www.ordenjuridico.gob.mx/index_ajn.php','www.ordenjuridico.gob.mx','official_informational_compilation',ARRAY['federal','state','municipal','treaties']::text[],'Compilación informativa. Verificar publicación federal en DOF y publicaciones locales en el medio oficial correspondiente. Índice localizado por búsqueda; su lectura directa tuvo timeout.') ON CONFLICT(source_id) DO UPDATE SET title=excluded.title,authority=excluded.authority,source_url=excluded.source_url,official_host=excluded.official_host,official_role=excluded.official_role,scope_levels=excluded.scope_levels,notes=excluded.notes;
INSERT INTO public.legal_sources(source_id,title,authority,source_url,official_host,official_role,scope_levels,notes) VALUES('mx_sre_treaties_current','SRE: tratados vigentes','Secretaría de Relaciones Exteriores','https://cja.sre.gob.mx/tratadosmexico/buscador','cja.sre.gob.mx','official_informational_catalog',ARRAY['treaties']::text[],'Catálogo informativo. Confirmar estado para México, publicación, reservas y fechas de efectos por instrumento; la fecha de adopción no sustituye entrada en vigor. La nota de alcance excluye acuerdos interinstitucionales.') ON CONFLICT(source_id) DO UPDATE SET title=excluded.title,authority=excluded.authority,source_url=excluded.source_url,official_host=excluded.official_host,official_role=excluded.official_role,scope_levels=excluded.scope_levels,notes=excluded.notes;
INSERT INTO public.legal_sources(source_id,title,authority,source_url,official_host,official_role,scope_levels,notes) VALUES('mx_sre_treaties_noncurrent','SRE: tratados no vigentes','Secretaría de Relaciones Exteriores','https://cja.sre.gob.mx/tratadosmexico/no-vigentes','cja.sre.gob.mx','official_informational_catalog',ARRAY['treaties']::text[],'Colección separada para cambios de estado e historia. No mezclar sus resultados con normas vigentes sin filtrar fecha y aplicabilidad.') ON CONFLICT(source_id) DO UPDATE SET title=excluded.title,authority=excluded.authority,source_url=excluded.source_url,official_host=excluded.official_host,official_role=excluded.official_role,scope_levels=excluded.scope_levels,notes=excluded.notes;
INSERT INTO public.legal_sources(source_id,title,authority,source_url,official_host,official_role,scope_levels,notes) VALUES('mx_scjn_sjf','Semanario Judicial de la Federación','Suprema Corte de Justicia de la Nación','https://sjfsemanal.scjn.gob.mx/presentacion','sjfsemanal.scjn.gob.mx','official_judicial_publication',ARRAY['judicial_criteria']::text[],'Colección judicial separada: revisar clase de criterio, publicación y aplicabilidad; no tratar toda tesis como una ley ni como criterio obligatorio.') ON CONFLICT(source_id) DO UPDATE SET title=excluded.title,authority=excluded.authority,source_url=excluded.source_url,official_host=excluded.official_host,official_role=excluded.official_role,scope_levels=excluded.scope_levels,notes=excluded.notes;
INSERT INTO public.legal_sources(source_id,title,authority,source_url,official_host,official_role,scope_levels,notes) VALUES('mx_inegi_geography','Catálogo Único de Áreas Geoestadísticas','Instituto Nacional de Estadística y Geografía','https://www.inegi.org.mx/app/ageeml/','www.inegi.org.mx','geographic_reference_not_law',ARRAY['geographic_inventory']::text[],'Sólo referencia territorial para nombres, claves e inventarios. No es fuente normativa ni acredita vigencia jurídica.') ON CONFLICT(source_id) DO UPDATE SET title=excluded.title,authority=excluded.authority,source_url=excluded.source_url,official_host=excluded.official_host,official_role=excluded.official_role,scope_levels=excluded.scope_levels,notes=excluded.notes;
